    line(ctx, x2 + dx - tick, y2 + dy, x2 + dx + tick, y2 + dy, INK_FAINT, 1);
  }
  const mx = (x1 + x2) / 2 + dx;
  const my = (y1 + y2) / 2 + dy;
  ctx.save();
  ctx.font = `10px ${FONT}`;
  const w = ctx.measureText(label).width + 10;
  ctx.fillStyle = PAPER;
